def seed_diet_preferences(apps, schema_editor):
    diet_preference = apps.get_model("accounts", "DietPreference")
    for code, label in [
        ("vegan", "Vegan"),
        ("vegetarian", "Vegetarian"),
        ("low-carb", "Low Carb"),
        ("keto", "Keto"),
    ]:
        diet_preference.objects.get_or_create(code=code, defaults={"label": label})


def remove_diet_preferences(apps, schema_editor):
    apps.get_model("accounts", "DietPreference").objects.filter(
        code__in=["vegan", "vegetarian", "low-carb", "keto"]
    ).delete()


